	assertPick(t, selectSession(t, r, "svc", 1, "s"), "a", "h1:1", 10)
	assertPick(t, selected(t, r, "svc", 1), "b", "h2:2", 20)

	if rel := releaseSession(t, r, "svc", 1, "s"); !rel.OK || !rel.Changed || rel.Revision != 1 {
		t.Fatalf("release: %+v", rel)
	}

