	t.Fatalf("release on an empty list: %+v", r)
}
// 8: repeat release is an unchanged success, not not_found.
if r := got.Results[8]; !r.OK || r.Changed || r.Revision != 2 {
	t.Fatalf("repeat release on the empty list: %+v", r)
}

